describe('Update Display Name - User Profile', () => {
  beforeEach(() => {
    cy.visit('/user-profile');
  });

  it('should successfully update display name and reflect changes across the app', () => {
    // Verify initial display name is shown
    cy.get('[data-testid="display-name-input"]').should('be.visible');
    cy.get('[data-testid="display-name-input"]').should('contain', 'John Doe');

    // Intercept API call to update display name
    cy.intercept('POST', '/api/user/update-display-name').as('updateDisplayName');

    // Update display name
    cy.get('[data-testid="display-name-input"]').type('Jane Smith');
    cy.get('[data-testid="update-display-name-button"]').click();

    // Wait for API call to complete
    cy.wait('@updateDisplayName');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Display name updated successfully');

    // Verify new display name is reflected in profile
    cy.get('[data-testid="display-name-input"]').should('contain', 'Jane Smith');

    // Verify email is still visible and unchanged
    cy.get('[data-testid="email-input"]').should('contain', 'john.doe@example.com');

    // Verify name is reflected in other parts of the app
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome, Jane Smith');
    cy.get('[data-testid="profile-card"]').should('contain', 'Jane Smith');

    // Verify name is reflected in notifications
    cy.get('[data-testid="notification-badge"]').should('contain', 'Jane Smith');

    // Verify name is reflected in search results
    cy.get('[data-testid="search-results"]').should('contain', 'Jane Smith');

    // Verify name is reflected in user settings
    cy.get('[data-testid="user-settings"]').should('contain', 'Jane Smith');

    // Verify name is reflected in user dashboard
    cy.get('[data-testid="user-dashboard"]').should('contain', 'Jane Smith');

    // Verify name is reflected in team notifications
    cy.get('[data-testid="team-notification"]').should('contain', 'Jane Smith');

    // Verify name is reflected in chat
    cy.get('[data-testid="chat-message"]').should('contain', 'Jane Smith');

    // Verify name is reflected in profile picture
    cy.get('[data-testid="profile-picture"]').should('have.attr', 'src');

    // Verify name is reflected in user profile URL
    cy.url().should('include', '/user/jane-smith');
  });

  it('should handle empty display name input and show validation error', () => {
    // Verify initial display name is shown
    cy.get('[data-testid="display-name-input"]').should('be.visible');
    cy.get('[data-testid="display-name-input"]').should('contain', 'John Doe');

    // Intercept API call to update display name
    cy.intercept('POST', '/api/user/update-display-name').as('updateDisplayName');

    // Attempt to update with empty input
    cy.get('[data-testid="display-name-input"]').clear().type('');
    cy.get('[data-testid="update-display-name-button"]').click();

    // Wait for API call to complete
    cy.wait('@updateDisplayName');

    // Verify validation error message appears
    cy.get('[data-testid="validation-error-message"]').should('be.visible');
    cy.get('[data-testid="validation-error-message"]').should('contain', 'Display name cannot be empty');

    // Verify empty display name is not reflected
    cy.get('[data-testid="display-name-input"]').should('contain', 'John Doe');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify error message is visible
    cy.get('[data-testid="validation-error-message"]').should('be.visible');

    // Verify error message contains correct error
    cy.get('[data-testid="validation-error-message"]').should('contain', 'Display name cannot be empty');

    // Verify user can retry with valid input
    cy.get('[data-testid="display-name-input"]').clear().type('Jane Smith');
    cy.get('[data-testid="update-display-name-button"]').click();

    // Wait for API call to complete
    cy.wait('@updateDisplayName');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Display name updated successfully');

    // Verify validation error message is gone
    cy.get('[data-testid="validation-error-message"]').should('not.exist');
  });
});
